{"sql": "SELECT repository_name_with_owner, repository_host_type, repository_size, repository_language, repository_fork_source_name_with_owner, repository_updated_timestamp
FROM `bigquery-public-data.libraries_io.projects_with_repository_fields`
WHERE repository_name_with_owner IN (
  'Informatievlaanderen/datadog-tracing', 'wildsebastian/nixpkgs', 'Ryan-Efendy/Swipeify',
  'pink/PennApps2015', 'ElleryW/deckard', 'incodehq/relatio', 'ccmdesign-archives/iodc18-osem-archive'
)"}

{"sql": "SELECT name_with_owner, host_type, size, language, fork_source_name_with_owner, updated_timestamp
FROM `bigquery-public-data.libraries_io.repositories`
WHERE name_with_owner IN (
  'Informatievlaanderen/datadog-tracing', 'wildsebastian/nixpkgs', 'Ryan-Efendy/Swipeify',
  'pink/PennApps2015', 'ElleryW/deckard', 'incodehq/relatio', 'ccmdesign-archives/iodc18-osem-archive'
